import{c as t,Q as a,j as i,m as s}from"./chunks/framework.DoOjWOm2.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/install-from-catalog.md","filePath":"plugins/install-from-catalog.md"}'),n={name:"plugins/install-from-catalog.md"};function o(r,e,l,d,h,g){return a(),i("div",null,[...e[0]||(e[0]=[s(`<p><strong>Phase:</strong> N (End-User Documentation) <strong>Step:</strong> N.14 <strong>Since:</strong> 0.18.0</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>The plugin catalog is a hub-hosted, browsable list of curated plugins — each signature-verified against the Phlix hub&#39;s published keys. Browse to <strong>Settings → Plugins → Browse Catalog</strong>, pick a plugin, click <strong>Install</strong>, and the verified plugin lands in one click. Catalog plugins carry SHA256 signatures and are moderated by the hub team, so you don&#39;t need to manage your own trusted-key allowlist for community plugins.</p><hr><h2 id="_1-what-is-the-plugin-catalog" tabindex="-1">1. What Is the Plugin Catalog <a class="header-anchor" href="#_1-what-is-the-plugin-catalog" aria-label="Permalink to &quot;1. What Is the Plugin Catalog&quot;">​</a></h2><p>The catalog is a JSON endpoint served by the Phlix hub (<code>https://catalog.phlix.media/v1/plugins</code> or similar), listing every community plugin that has passed hub moderation and carries a valid signature from a registered author. Operators can browse by plugin type, search by name, and install in one click. The catalog replaces manual URL pasting for operators who prefer curated plugins.</p><p>Plugin types available in the catalog: <code>metadata-provider</code>, <code>auth-provider</code>, <code>notifier</code>, <code>scrobbler</code>, <code>tuner</code>, <code>transcoder-hook</code>, <code>ui-theme</code>, <code>library-type</code>, <code>subtitle-provider</code>, <code>arr-integration</code>, <code>analytics-sink</code>.</p><hr><h2 id="_2-browse-and-install-from-the-web-ui" tabindex="-1">2. Browse and Install from the Web UI <a class="header-anchor" href="#_2-browse-and-install-from-the-web-ui" aria-label="Permalink to &quot;2. Browse and Install from the Web UI&quot;">​</a></h2><ol><li>Browse to <strong>Settings → Plugins</strong> (or <code>/admin/plugins</code>).</li><li>Click <strong>Browse Catalog</strong> (or navigate directly to <code>/admin/plugins/catalog</code>).</li><li>Use the <strong>type filter</strong> dropdown to narrow by category (<code>metadata-provider</code>, <code>auth-provider</code>, <code>notifier</code>, <code>scrobbler</code>, <code>tuner</code>, <code>transcoder-hook</code>, <code>ui-theme</code>, etc.).</li><li>Click a plugin card to expand its detail panel: description, author, version, <code>phlix_min_server_version</code>, signature status.</li><li>Click <strong>Install</strong> on the chosen plugin.</li><li>The plugin is downloaded, signature-verified, and staged automatically.</li><li>It lands <strong>disabled</strong> in the plugins table — flip the toggle to enable.</li></ol><p>Screenshot placeholder: <code>[screenshot: plugin catalog browse view with type filter and install button]</code></p><hr><h2 id="_3-enabling-and-configuring" tabindex="-1">3. Enabling and Configuring <a class="header-anchor" href="#_3-enabling-and-configuring" aria-label="Permalink to &quot;3. Enabling and Configuring&quot;">​</a></h2><p>After install:</p><ul><li><strong>Enable:</strong> flip the toggle in <strong>Settings → Plugins</strong> table.</li><li><strong>Configure:</strong> click the wrench icon to open the plugin&#39;s settings form. Settings vary by plugin type:</li></ul><table tabindex="0"><thead><tr><th>Plugin Type</th><th>Typical Config Fields</th></tr></thead><tbody><tr><td><code>metadata-provider</code></td><td>API key, endpoint URL</td></tr><tr><td><code>auth-provider</code></td><td>Provider URL, client ID/secret, scopes</td></tr><tr><td><code>notifier</code></td><td>Webhook URL, channel/room, auth token</td></tr><tr><td><code>scrobbler</code></td><td>Service credentials</td></tr><tr><td><code>tuner</code></td><td>Device ID, lineup URL</td></tr><tr><td><code>transcoder-hook</code></td><td>Priority, encoding profile</td></tr><tr><td><code>ui-theme</code></td><td>No required config — applies immediately on enable</td></tr></tbody></table><p>Settings are persisted in the <code>plugins.settings_json</code> column. Each plugin exposes its own fields as declared in its <code>plugin.json</code> <code>settings</code> block.</p><hr><h2 id="_4-updating-catalog-plugins" tabindex="-1">4. Updating Catalog Plugins <a class="header-anchor" href="#_4-updating-catalog-plugins" aria-label="Permalink to &quot;4. Updating Catalog Plugins&quot;">​</a></h2><p>When a catalog plugin ships a new version:</p><ul><li>A badge appears on the plugin card in the catalog view.</li><li>The <strong>Update</strong> button triggers <code>install</code> again; the loader replaces on-disk files and retains <code>enabled</code> state and <code>settings_json</code>.</li><li>After update, the plugin auto-re-attaches on the next server restart (or immediately if it does not require restart — see Failure 3 below).</li></ul><hr><h2 id="_5-removing-a-catalog-plugin" tabindex="-1">5. Removing a Catalog Plugin <a class="header-anchor" href="#_5-removing-a-catalog-plugin" aria-label="Permalink to &quot;5. Removing a Catalog Plugin&quot;">​</a></h2><p>Same as URL-installed plugins: <strong>Settings → Plugins</strong> → toggle <strong>Disable</strong> → click <strong>Uninstall</strong>. This removes the on-disk files and the database row. Catalog browsing state is preserved (the plugin remains browsable in the catalog; you can reinstall).</p><hr><h2 id="_6-what-can-go-wrong" tabindex="-1">6. What Can Go Wrong <a class="header-anchor" href="#_6-what-can-go-wrong" aria-label="Permalink to &quot;6. What Can Go Wrong&quot;">​</a></h2><h3 id="failure-1-version-incompatibility" tabindex="-1">Failure 1: Version Incompatibility <a class="header-anchor" href="#failure-1-version-incompatibility" aria-label="Permalink to &quot;Failure 1: Version Incompatibility&quot;">​</a></h3><p><strong>Symptom:</strong> &quot;This plugin requires phlix-server ≥ 1.2.0; you are running 1.1.4&quot; shown in the catalog detail panel.</p><p><strong>Cause:</strong> Running server is older than the plugin&#39;s <code>phlix_min_server_version</code>.</p><p><strong>Fix:</strong> Upgrade phlix-server before installing. The catalog shows compatibility info before you install — pay attention to the version badge.</p><hr><h3 id="failure-2-signature-verification-failure" tabindex="-1">Failure 2: Signature Verification Failure <a class="header-anchor" href="#failure-2-signature-verification-failure" aria-label="Permalink to &quot;Failure 2: Signature Verification Failure&quot;">​</a></h3><p><strong>Symptom:</strong> Install fails with &quot;Signature verification failed.&quot;</p><p><strong>Cause:</strong> Plugin tarball was corrupted during download, or hub moderation was bypassed.</p><p><strong>Fix:</strong> Report to hub moderation at <a href="https://github.com/detain/phlix-plugin-catalog" target="_blank" rel="noreferrer">github.com/detain/phlix-plugin-catalog</a>. Do not bypass the signature check manually.</p><hr><h3 id="failure-3-plugin-requires-restart" tabindex="-1">Failure 3: Plugin Requires Restart <a class="header-anchor" href="#failure-3-plugin-requires-restart" aria-label="Permalink to &quot;Failure 3: Plugin Requires Restart&quot;">​</a></h3><p><strong>Symptom:</strong> Plugin is enabled but its hooks do not fire (e.g., <code>transcoder-hook</code> never intercepts a transcode).</p><p><strong>Cause:</strong> Plugin registers event listeners only at container boot, not on enable.</p><p><strong>Fix:</strong> Restart phlix-server:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> phlix</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/phlix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span></span></code></pre></div><p>The plugin auto-re-attaches on boot for enabled plugins.</p><hr><h3 id="failure-4-ui-theme-css-breaks-web-portal" tabindex="-1">Failure 4: ui-theme CSS Breaks Web Portal <a class="header-anchor" href="#failure-4-ui-theme-css-breaks-web-portal" aria-label="Permalink to &quot;Failure 4: ui-theme CSS Breaks Web Portal&quot;">​</a></h3><p><strong>Symptom:</strong> Web portal blank or partially styled after enabling a <code>ui-theme</code>.</p><p><strong>Cause:</strong> Theme uses CSS selectors that conflict with the current portal DOM structure.</p><p><strong>Fix:</strong> Disable immediately via CLI:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sS</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://phlix.example.com/api/v1/admin/plugins/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/disable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>Then contact the plugin author with your Phlix server version and portal DOM details.</p><hr><h2 id="_7-next-steps" tabindex="-1">7. Next Steps <a class="header-anchor" href="#_7-next-steps" aria-label="Permalink to &quot;7. Next Steps&quot;">​</a></h2><ul><li><a href="./install-from-url.html">Install from URL</a> — for plugins not yet in the catalog, or for testing unreleased versions</li><li><a href="./trusted-plugin-list.html">Trusted plugin list</a> — how the hub&#39;s signature allowlist works and how to request plugin listing</li><li><a href="./developer-guide.html">Plugin developer guide</a> — for plugin authors; learn how to publish a plugin to the catalog</li><li><a href="https://github.com/detain/phlix-plugin-catalog" target="_blank" rel="noreferrer">Plugin catalog source</a> — file an issue or PR to add or update a community plugin listing</li></ul>`,52)])])}const u=t(n,[["render",o]]);export{c as __pageData,u as default};
